class Base {
    // Contains implicit vptr pointing to Base's VTable
public:
    virtual void func_a() const = 0;
    virtual void func_b() const;
    virtual ~Base() = default;
};

class Derived : public Base {
public:
    void func_a() const override;
    // Derived object reuses Base's vptr slot, points to Derived VTable
};

// Vtable (Compiler Generated):
// [0]: &Derived::~Derived
// [1]: &Derived::func_a
// [2]: &Base::func_b

Derived d_obj;
Base* ptr = &d_obj;
// Runtime dispatch: ptr->vptr -> VTable[1] -> Derived::func_a
ptr->func_a();
// Vptr usually first member (offset 0) for single inheritance
